#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cstring>
#include <ArduinoJson.h>

struct BatteryState {
    float bat_voltage=0,bat_current=0,starter_voltage=0;
    int bat_soc=0;
    uint8_t battery_fields=0;
    uint32_t bat_voltage_updated_ms=0,bat_current_updated_ms=0,bat_soc_updated_ms=0;
} state;
struct StateLockGuard {};
static uint32_t test_clock=100;
static uint32_t millis(){return test_clock;}
// Generated by test_battery_soc.py from the actual production parser/helpers.
#include "battery_soc_under_test.h"

static void check(bool condition,const char *message) {
    if(!condition){std::fprintf(stderr,"FAIL: %s (SOC=%d, fields=%u, SOC time=%u)\n",message,state.bat_soc,state.battery_fields,state.bat_soc_updated_ms);std::exit(1);}
}
int main() {
    // Exact /batt JSON visible in Nightman's forum screenshot (post 119).
    parse_batt_json(R"({"VoltB":26.63,"Ampere":-0.8,"battsoc":96.5})");
    check(state.bat_soc==96 && state.battery_fields==7 && state.bat_soc_updated_ms==100,"numeric decimal SOC from forum screenshot");
    check(std::fabs(state.bat_voltage-26.63f)<0.001f && std::fabs(state.bat_current+0.8f)<0.001f,"voltage/current remain unchanged");
    struct Case {const char *payload;int expected;};
    const Case cases[]={
        {R"({"battsoc":91.9})",91},{R"({"battsoc":91})",91},
        {R"({"battsoc":"91.9"})",91},{R"({"battsoc":"91,9"})",91},
        {R"({"battsoc":" 91,9 \t"})",91},{R"({"battsoc":91.0})",91},
        {R"({"battsoc":0})",0},{R"({"battsoc":0.9})",0},
        {R"({"battsoc":"0,0"})",0},{R"({"battsoc":100})",100},
        {R"({"battsoc":100.0})",100},{R"({"battsoc":"100.0"})",100}
    };
    for(const auto &c:cases) {
        ++test_clock;parse_batt_json(c.payload);
        check(state.bat_soc==c.expected && state.bat_soc_updated_ms==test_clock,"supported number/string must update consistently");
    }
    // Invalid/missing samples must never become fresh zeroes or erase good SOC.
    const char *invalid[]={R"({})",R"({"battsoc":null})",R"({"battsoc":true})",R"({"battsoc":false})",
        R"({"battsoc":""})",R"({"battsoc":" "})",R"({"battsoc":"NaN"})",R"({"battsoc":"Infinity"})",
        R"({"battsoc":-0.1})",R"({"battsoc":100.1})",R"({"battsoc":"101"})",
        R"({"battsoc":"91.9%"})",R"({"battsoc":"91.9junk"})",R"({"battsoc":[]})",
        R"({"battsoc":{}})",R"({"battsoc":1e100})",R"({"battsoc":)"};
    for(const char *payload:invalid) {
        state=BatteryState();state.bat_soc=73;state.battery_fields=4;state.bat_soc_updated_ms=25;
        ++test_clock;parse_batt_json(payload);
        check(state.bat_soc==73 && state.battery_fields==4 && state.bat_soc_updated_ms==25,"invalid sample must preserve value, validity and timestamp");
        state=BatteryState();++test_clock;parse_batt_json(payload);
        check(!(state.battery_fields&4) && state.bat_soc_updated_ms==0,"invalid first sample must not fabricate valid SOC");
    }
    state=BatteryState();state.bat_soc=73;state.battery_fields=4;state.bat_soc_updated_ms=25;
    ++test_clock;parse_batt_json(R"({"VoltB":13.4,"Ampere":-2.5,"battsoc":null})");
    check(state.bat_soc==73 && state.bat_soc_updated_ms==25 && state.battery_fields==7,"invalid SOC must not suppress valid voltage/current");
    check(state.bat_voltage_updated_ms==test_clock && state.bat_current_updated_ms==test_clock,"only accepted fields refresh timestamps");
    std::puts("PASS: actual /batt parser, numeric/string decimal SOC, limits, invalid samples and freshness.");
}
